#!/usr/bin/env bash
# After H6 train.done: wait H5c n80 off chall:8002 → merge LoRA → chall → n80.
# TalentPigs-init (same base as king). Do NOT edit this file while it is live.
set -euo pipefail

# shellcheck disable=SC1091
source /root/venv/bin/activate
if [[ -f /root/mine.env ]]; then
  set -a
  # shellcheck disable=SC1091
  source /root/mine.env
  set +a
fi
export HF_TOKEN="${HF_TOKEN:-}"
export HF_HOME=${HF_HOME:-/root/hf}
export PYTHONPATH=/root/mining_src/affine_pkg:${PYTHONPATH:-}
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-6,7}

BASE=${BASE:-/root/hf/hub/models--TalentPigs--affine-5ekxlcg3fx-abc/snapshots/dbfbb3e2a17c7603e7fc68a3a15b343f42dfdef4}
KING_REPO=${KING_REPO:-TalentPigs/affine-5ekxlcg3fx-abc}
KING_REV=${KING_REV:-dbfbb3e2a17c7603e7fc68a3a15b343f42dfdef4}
TRAIN_DIR=${TRAIN_DIR:-/root/h6/train}
ADAPTER=${ADAPTER:-$TRAIN_DIR/adapter}
CKPT_ROOT=${CKPT_ROOT:-$TRAIN_DIR/checkpoints}
MERGED=${MERGED:-/root/h6/merged}
SIM_N80=/root/affine_data/h6_sim_result.json
PROG=/root/affine_data/h6_sim_progress.json
LOG=/root/logs/h6_pipeline.nohup
SOFT_DEADLINE_UTC=${SOFT_DEADLINE_UTC:-2026-08-07T18:00:00Z}
DEADMAN_UTC=${DEADMAN_UTC:-2026-08-07T19:00:00Z}

log() { echo "[h6-pipe] $(date -u +%Y-%m-%dT%H:%M:%SZ) $*" | tee -a "$LOG"; }

_train_alive() {
  if [[ -f /root/logs/h6_train.pid ]]; then
    local tpid
    tpid=$(cat /root/logs/h6_train.pid 2>/dev/null || true)
    if [[ -n "${tpid:-}" ]] && kill -0 "$tpid" 2>/dev/null; then
      return 0
    fi
  fi
  pgrep -f "python3 /root/mining_src/s4-h1v2-sft/train_lora.py --base" >/dev/null 2>&1
}

_h5c_sim_busy() {
  if [[ -f /root/logs/h5c_sim_n80.done ]] || [[ -f /root/affine_data/h5c_sim_result.json ]]; then
    return 1
  fi
  pgrep -f "run_sim_duel.py .*local-h5c" >/dev/null 2>&1
}

_abort_on_exit() {
  local rc=$?
  if [[ $rc -eq 0 ]]; then
    return 0
  fi
  if [[ -f /root/logs/h6_pipeline.done ]]; then
    return 0
  fi
  if [[ ! -f /root/logs/h6_pipeline.aborted ]]; then
    echo "aborted_err_rc=${rc} $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      >/root/logs/h6_pipeline.aborted
    log "EXIT trap wrote aborted_err_rc=${rc}" || true
  fi
}
trap _abort_on_exit EXIT

mkdir -p /root/logs /root/affine_data /root/h6
rm -f /root/logs/h6_pipeline.aborted /root/logs/h6_pipeline.done \
  /root/logs/h6_merge.done /root/logs/h6_chall_serve.done \
  /root/logs/h6_sim_n80.done

log "waiting for $TRAIN_DIR/train.done (or adapter + no train proc)"
_wait_i=0
while true; do
  if [[ -f "$TRAIN_DIR/train.done" ]]; then
    log "train.done present"
    break
  fi
  if [[ -f "$ADAPTER/adapter_config.json" ]] && ! _train_alive; then
    log "adapter present and train proc gone - proceed"
    break
  fi
  now=$(date -u +%s)
  soft=$(date -u -d "$SOFT_DEADLINE_UTC" +%s)
  if (( now > soft - 3600 )); then
    log "WARN: <60m to soft and train not done; abort"
    echo "aborted_no_train $(date -u +%Y-%m-%dT%H:%M:%SZ)" > /root/logs/h6_pipeline.aborted
    exit 1
  fi
  _wait_i=$((_wait_i + 1))
  if (( _wait_i % 10 == 0 )); then
    log "still waiting for train.done (poll #$_wait_i)"
  fi
  sleep 30
done

log "waiting for train pid to exit and release GPUs 6,7"
for _ in $(seq 1 180); do
  if ! _train_alive; then
    log "train proc gone"
    break
  fi
  sleep 5
done
if _train_alive; then
  log "ERROR: train still alive >15m after train.done; abort"
  echo "aborted_train_stuck $(date -u +%Y-%m-%dT%H:%M:%SZ)" > /root/logs/h6_pipeline.aborted
  exit 1
fi
sleep 15
log "GPU settle done; proceeding to merge"

if [[ ! -f "$ADAPTER/adapter_config.json" ]]; then
  latest=$(ls -d "$CKPT_ROOT"/checkpoint-* 2>/dev/null | sort -V | tail -1 || true)
  if [[ -n "${latest:-}" && -f "$latest/adapter_config.json" ]]; then
    ADAPTER=$latest
    log "using checkpoint adapter $ADAPTER"
  else
    log "ERROR: no adapter"
    echo "aborted_no_adapter $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      >/root/logs/h6_pipeline.aborted
    exit 1
  fi
fi

log "merge LoRA → $MERGED"
rm -rf "$MERGED"
python /root/mining_src/s4-h1-sft/merge_lora.py \
  --base "$BASE" \
  --adapter "$ADAPTER" \
  --out "$MERGED" \
  --device-map auto \
  | tee -a "$LOG"
cp -f "$MERGED/merge_meta.json" /root/affine_data/h6_merge_meta.json 2>/dev/null || true
date -u +%Y-%m-%dT%H:%M:%SZ > /root/logs/h6_merge.done

python - <<PY 2>&1 | tee -a "$LOG"
import hashlib, json, sys
from pathlib import Path

merged = Path("$MERGED")
king = Path("$BASE")
meta_path = merged / "merge_meta.json"
meta = json.loads(meta_path.read_text()) if meta_path.is_file() else {}


def window_sha(path: Path, offset: int, nbytes: int = 1 << 20) -> str:
    h = hashlib.sha256()
    size = path.stat().st_size
    off = max(0, min(offset, max(0, size - nbytes)))
    with open(path, "rb") as f:
        f.seek(off)
        h.update(f.read(nbytes))
    return h.hexdigest()


def numbered(p: Path):
    shards = sorted(p.glob("model-*-of-*.safetensors"))
    if shards:
        return shards
    return sorted(x for x in p.glob("model-*.safetensors") if "visual" not in x.name)


ms, ks = numbered(merged), numbered(king)
if not ms or not ks:
    sys.exit("REFUSE: missing language-model shards")

by_name = {k.name: k for k in ks}
pairs = [(m, by_name[m.name]) for m in ms if m.name in by_name]
if not pairs:
    n = min(len(ms), len(ks))
    pairs = list(zip(ms[:n], ks[:n]))

any_diff = False
for m, k in pairs:
    size = k.stat().st_size
    eqs = {
        "head": window_sha(k, 0) == window_sha(m, 0),
        "mid": window_sha(k, size // 2) == window_sha(m, size // 2),
        "tail": window_sha(k, max(0, size - (1 << 20)))
        == window_sha(m, max(0, m.stat().st_size - (1 << 20))),
    }
    if not all(eqs.values()):
        any_diff = True

merge_meta_identical = bool(meta.get("weight_identical"))
identical = merge_meta_identical or (not any_diff and len(pairs) > 0)
payload = {
    "merge_meta_weight_identical": merge_meta_identical,
    "window_any_diff": any_diff,
    "identical_to_king": identical,
    "note": "TalentPigs-init LoRA: first_1MiB may match; refuse only if all windows equal",
}
Path("/root/affine_data/h6_identity.json").write_text(json.dumps(payload, indent=2) + "\n")
print(json.dumps(payload, indent=2), flush=True)
if identical:
    sys.exit("REFUSE: merged weight-identical to TalentPigs king")
print("[h6] OK_NON_IDENTICAL_VS_KING", flush=True)
PY

HF_LORA_REPO=${HF_LORA_REPO:-unconst/Affine-5czsc2fc98-h6-lora}
HF_MERGED_REPO=${HF_MERGED_REPO:-unconst/Affine-5czsc2fc98-h6-merged}
HF_BASE_HUB=${HF_BASE_HUB:-TalentPigs/affine-5ekxlcg3fx-abc}
if [[ -n "${HF_TOKEN:-}" ]]; then
  log "background HF push adapter → $HF_LORA_REPO"
  nohup python3 /root/mining_src/s4-h1-sft/salvage_adapter.py \
    --adapter "$ADAPTER" \
    --repo "$HF_LORA_REPO" \
    --base-hub "$HF_BASE_HUB" \
    --commit-message "H6 TalentPigs-init shortz-nolist LoRA salvage (TTL insurance; not a submission)" \
    --out-meta /root/affine_data/h6_adapter_salvage.json \
    >>/root/logs/h6_push_adapter.nohup 2>&1 &
  echo $! >/root/logs/h6_push_adapter.pid
  log "background HF push merged → $HF_MERGED_REPO (public, non-blocking)"
  nohup python3 /root/mining_src/s4-h1-sft/push_merged.py \
    --merged "$MERGED" \
    --repo "$HF_MERGED_REPO" \
    --public \
    --commit-message "H6 TalentPigs-init shortz-nolist merged salvage (TTL insurance; not a submission)" \
    --out-meta /root/affine_data/h6_merged_salvage.json \
    >>/root/logs/h6_push_merged.nohup 2>&1 &
  echo $! >/root/logs/h6_push_merged.pid
else
  log "WARN: HF_TOKEN unset; skipping H6 HF salvage pushes"
fi

# H5c owns chall:8002 until its n80 lands — do not swap early.
log "waiting for H5c n80 to free chall:8002"
_wait_i=0
while _h5c_sim_busy; do
  now=$(date -u +%s)
  soft=$(date -u -d "$SOFT_DEADLINE_UTC" +%s)
  if (( now > soft - 3600 )); then
    log "WARN: <60m to soft and H5c n80 still busy; abort"
    echo "aborted_h5c_n80_blocks $(date -u +%Y-%m-%dT%H:%M:%SZ)" > /root/logs/h6_pipeline.aborted
    exit 1
  fi
  _wait_i=$((_wait_i + 1))
  if (( _wait_i % 10 == 0 )); then
    log "still waiting for H5c n80 (poll #$_wait_i)"
  fi
  sleep 30
done
log "H5c n80 clear (result or done stamp)"

code_t=$(curl -s -o /dev/null -w "%{http_code}" --max-time 3 http://127.0.0.1:8000/health || true)
code_k=$(curl -s -o /dev/null -w "%{http_code}" --max-time 3 http://127.0.0.1:8001/health || true)
if [[ "$code_t" != "200" || "$code_k" != "200" ]]; then
  log "ABORT: teacher/king unhealthy t=$code_t k=$code_k"
  echo "aborted_engines_unhealthy $(date -u +%Y-%m-%dT%H:%M:%SZ)" > /root/logs/h6_pipeline.aborted
  exit 1
fi

unset CUDA_VISIBLE_DEVICES
log "chall-only re-serve $MERGED (keep teacher+TalentPigs king)"
RESTART_KING=0 \
  MERGE="$MERGED" \
  KEVIN_REPO="$KING_REPO" \
  KEVIN_REV="$KING_REV" \
  TEACHER_REPO=${TEACHER_REPO:-zai-org/GLM-4.5-Air-FP8} \
  TEACHER_REV=${TEACHER_REV:-} \
  bash /root/mining_src/s4-h2-merge/restart_for_h2.sh
date -u +%Y-%m-%dT%H:%M:%SZ > /root/logs/h6_chall_serve.done
log "CHALL_SERVE_DONE"

now=$(date -u +%s)
dead=$(date -u -d "$DEADMAN_UTC" +%s)
if (( dead - now < 2400 )); then
  log "ABORT: <40m to deadman; skip n80"
  echo "aborted_no_n80_budget $(date -u +%Y-%m-%dT%H:%M:%SZ)" > /root/logs/h6_pipeline.aborted
  exit 1
fi

N80_MAX_ATTEMPTS=${N80_MAX_ATTEMPTS:-3}
n80_ok=0
for attempt in $(seq 1 "$N80_MAX_ATTEMPTS"); do
  now=$(date -u +%s)
  dead=$(date -u -d "$DEADMAN_UTC" +%s)
  if (( dead - now < 2400 )); then
    log "ABORT: <40m to deadman before n80 attempt $attempt; stop"
    echo "aborted_no_n80_budget attempt=$attempt $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      > /root/logs/h6_pipeline.aborted
    exit 1
  fi
  rm -f "$SIM_N80" "$PROG" /root/logs/h6_sim_n80.done
  log "launch n80 sim attempt $attempt/$N80_MAX_ATTEMPTS → $SIM_N80"
  set +e
  python /root/mining_src/s4-h2-merge/run_sim_duel.py \
    --king-repo "$KING_REPO" \
    --king-rev "$KING_REV" \
    --chall-repo "$MERGED" \
    --chall-rev local \
    --n-turns 80 \
    --hotkey local-h6 \
    --out "$SIM_N80" \
    --progress-out "$PROG" \
    --save-artifact \
    2>&1 | tee -a /root/logs/h6_sim.nohup
  sim_rc=${PIPESTATUS[0]}
  set -e
  if [[ "$sim_rc" -eq 0 && -f "$SIM_N80" ]]; then
    n80_ok=1
    log "n80 attempt $attempt OK"
    break
  fi
  log "WARN: n80 attempt $attempt failed rc=$sim_rc; will retry if budget"
  sleep 15
done
if [[ "$n80_ok" -ne 1 ]]; then
  log "ERROR: n80 failed after $N80_MAX_ATTEMPTS attempts"
  echo "aborted_n80_failed $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    > /root/logs/h6_pipeline.aborted
  exit 1
fi

python3 - <<'PY'
import json
from datetime import datetime, timezone
from pathlib import Path

raw = json.loads(Path("/root/affine_data/h6_sim_result.json").read_text())
v = raw.get("verdict") or {}
h4 = raw.get("h4") or {}
king = v.get("king") or {}
chal = v.get("challenger") or {}
margin = v.get("margin")
z = v.get("z")
r = h4.get("chall_r")
if r is None:
    r = chal.get("calib_ratio")
kb = king.get("baseline_abs") or 0.0
cb = chal.get("baseline_abs") or 0.0
base_x = (cb / kb) if kb else None
valid = bool(king.get("valid")) and bool(chal.get("valid"))
# Real gates only: r∈[0.3,4.0] + baseline≤1.25× (encoded in chall.valid).
# Invented H4 band [0.70,0.85] is REFUTED — do not require it.
r_ok = r is not None and 0.3 <= float(r) <= 4.0
if margin is not None and margin > 0.04 and valid and r_ok:
    decision = "ADVANCE_STAGE5"
elif margin is not None and margin >= 0.02 and valid and r_ok:
    decision = "ITERATE"
else:
    decision = "REFUTE_H6"
dec = {
    "utc": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "margin": margin,
    "z": z,
    "se": v.get("se"),
    "r_c": r,
    "base_x": base_x,
    "valid_c": chal.get("valid"),
    "valid_k": king.get("valid"),
    "S_c": chal.get("S"),
    "S_k": king.get("S"),
    "r_ok": r_ok,
    "decision": decision,
    "submit": decision == "ADVANCE_STAGE5",
}
Path("/root/affine_data/h6_decision.json").write_text(json.dumps(dec, indent=2) + "\n")
print(json.dumps(dec, indent=2))
PY

date -u +%Y-%m-%dT%H:%M:%SZ > /root/logs/h6_sim_n80.done
date -u +%Y-%m-%dT%H:%M:%SZ > /root/logs/h6_pipeline.done
log "SIM_DONE decision=$(python3 -c "import json;print(json.load(open('/root/affine_data/h6_decision.json'))['decision'])")"
log "PIPELINE_DONE"
